+// Sales from the till: each dish sold uses one portion of its recipe per
+// unit of `qty`. A ticket is booked once; booking a file is all or nothing.
+import { AppError } from "../errors.js";
+import { dayOf } from "../dates.js";
+import { consume } from "./batches.js";
+import { getItem, onHand } from "./items.js";
+import { getDish } from "./menu.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+const round3 = (n) => Math.round(n * 1000) / 1000;
+
+/** True when a ticket has already been booked. */
+export function hasTicket(store, ticket) {
+  return (store.data.sales ?? []).some((s) => s.ticket === ticket);
+}
+
+// Ingredient quantities one sale line uses.
+function lineNeeds(store, line) {
+  return scaled(getRecipe(store, getDish(store, line.dishId).recipeId), line.qty);
+}
+
+/**
+ * Books sale lines { row, ticket, soldAt, dishId, qty }. Tickets already
+ * booked are skipped. Checks all stock first; throws sale_not_enough_stock
+ * naming the row where an item runs out, and then changes nothing.
+ * Returns { tickets, dishes } for what was booked.
+ */
+export function bookSales(store, lines) {
+  const fresh = lines.filter((l) => !hasTicket(store, l.ticket));
+  const needed = new Map();
+  for (const line of fresh) {
+    for (const n of lineNeeds(store, line)) {
+      const total = round3((needed.get(n.itemId) ?? 0) + n.qty);
+      const available = onHand(store, n.itemId);
+      if (total > available) {
+        const item = getItem(store, n.itemId);
+        throw new AppError("sale_not_enough_stock", { row: line.row, item: item.name, available, unit: item.unit });
+      }
+      needed.set(n.itemId, total);
+    }
+  }
+  // Stock was checked above; the snapshot keeps the file all or nothing even
+  // if a later step fails.
+  const before = structuredClone({ batches: store.data.batches, movements: store.data.movements, sales: store.data.sales, seq: store.data.seq });
+  try {
+    store.data.sales ??= [];
+    for (const line of fresh) {
+      for (const n of lineNeeds(store, line)) {
+        if (n.qty > 0) consume(store, n.itemId, n.qty, { at: line.soldAt, ref: `sale:${line.ticket}` });
+      }
+      store.data.sales.push({ id: store.nextId("sale"), ticket: line.ticket, soldAt: line.soldAt, dishId: line.dishId, qty: line.qty });
+    }
+  } catch (e) {
+    Object.assign(store.data, before);
+    if (before.sales === undefined) delete store.data.sales;
+    throw e;
+  }
+  return { tickets: new Set(fresh.map((l) => l.ticket)).size, dishes: fresh.reduce((s, l) => s + l.qty, 0) };
+}
+
+/**
+ * Variance per item between two days (inclusive): theoretical use from
+ * sales, actual use from consume movements, and actual minus theoretical.
+ */
+export function varianceReport(store, from, to) {
+  const inRange = (at) => {
+    const day = dayOf(at);
+    return day >= from && day <= to;
+  };
+  const rows = new Map();
+  const row = (itemId) => {
+    if (!rows.has(itemId)) rows.set(itemId, { theoretical: 0, actual: 0 });
+    return rows.get(itemId);
+  };
+  for (const sale of store.data.sales ?? []) {
+    if (!inRange(sale.soldAt)) continue;
+    for (const n of lineNeeds(store, sale)) row(n.itemId).theoretical += n.qty;
+  }
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || !inRange(m.at)) continue;
+    const batch = store.data.batches.find((b) => b.id === m.batchId);
+    if (batch) row(batch.itemId).actual += m.qty;
+  }
+  return [...rows]
+    .map(([itemId, r]) => {
+      const theoretical = round3(r.theoretical);
+      const actual = round3(r.actual);
+      return { itemId, name: getItem(store, itemId).name, theoretical, actual, difference: round3(actual - theoretical) };
+    })
+    .filter((r) => r.theoretical > 0 || r.actual > 0)
+    .sort((a, b) => a.itemId - b.itemId);
+}
